function buildCustomEpisode(title) {
  const createdAtMs = Date.now();
  return {
    id: `episode-${createdAtMs}`,
    title,
    status: "草稿",
    createdAt: formatEpisodeDate(createdAtMs),
    createdAtMs,
    storyboardCount: 0,
  };
}

function createEpisodeEntryList(episodes) {
  return [...episodes].sort(
    (left, right) => getEpisodeTimestamp(right) - getEpisodeTimestamp(left),
  );
}

function getEpisodeTimestamp(episode) {
  if (typeof episode?.createdAtMs === "number" && Number.isFinite(episode.createdAtMs)) {
    return episode.createdAtMs;
  }
  const parsed = Date.parse(String(episode?.createdAt ?? "").replace(/\./g, "/"));
  return Number.isFinite(parsed) ? parsed : 0;
}

function getNextEpisodeTitle(episodes) {
  const nextIndex = (Array.isArray(episodes) ? episodes.length : 0) + 1;
  return `第 ${nextIndex} 集`;
}

function buildSingleEpisodeTitle(scriptText, episodes) {
  const normalized = String(scriptText ?? "")
    .replace(/\r/g, "")
    .split("\n")
    .map((line) => line.trim())
    .find(Boolean);
  if (!normalized) {
    return getNextEpisodeTitle(episodes);
  }

  const candidate = normalized.replace(/[，。！？、…,.!? ]+$/g, "").trim();
  if (!candidate) {
    return getNextEpisodeTitle(episodes);
  }

  return [...candidate].slice(0, 24).join("");
}

function formatEpisodeDate(value) {
  const date = new Date(value);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}/${month}/${day}`;
}

function createTeamMemberDraft() {
  return {
    teamAccount: "",
    memberLoginAccount: "",
    displayName: "",
    password: "",
    initialCredits: 0,
    remark: "",
    projectIds: [],
    scriptIds: [],
    canvasIds: [],
    directorDeskIds: [],
    resourceSelectionDirty: false,
    resourcePickerType: "",
    resourcePickerPage: 1,
    resourcePagination: {},
    resourceCounts: {},
    selectedResourcesByType: {},
  };
}

function collectAssignableResourceIds(selectedIds, availableResources) {
  const selected = new Set(
    (Array.isArray(selectedIds) ? selectedIds : [])
      .map((item) => String(item ?? "").trim())
      .filter(Boolean),
  );
  const ids = [];
  (Array.isArray(availableResources) ? availableResources : []).forEach((resource) => {
    const resourceId = String(resource?.id ?? "").trim();
    if (!resourceId || !selected.has(resourceId)) {
      return;
    }
    ids.push(resourceId);
  });
  return { ids: [...new Set(ids)] };
}

function normalizeSelectedResourceIds(selectedIds) {
  return [
    ...new Set(
      (Array.isArray(selectedIds) ? selectedIds : [])
        .map((item) => String(item ?? "").trim())
        .filter(Boolean),
    ),
  ];
}

function mergeCachedTeamMemberResources(workbench, resourceType, resources) {
  const cached = Object.values(workbench.ui.teamMemberDraft?.selectedResourcesByType?.[resourceType] ?? {});
  return [
    ...(Array.isArray(resources) ? resources : []),
    ...cached,
  ];
}

function rememberSelectedTeamMemberResource(workbench, resourceType, resourceId) {
  const normalizedId = String(resourceId ?? "").trim();
  if (!normalizedId || (resourceType !== "project" && resourceType !== "script" && resourceType !== "canvas")) {
    return;
  }
  const listKey = resourceType === "project"
    ? "projectLibrary"
    : resourceType === "script"
      ? "scriptLibraryRecords"
      : "canvasProjects";
  const resource = (Array.isArray(workbench.ui?.[listKey]) ? workbench.ui[listKey] : [])
    .find((item) => String(item?.id ?? "") === normalizedId);
  if (!resource) {
    return;
  }
  const currentCache = workbench.ui.teamMemberDraft?.selectedResourcesByType ?? {};
  workbench.ui.teamMemberDraft = {
    ...(workbench.ui.teamMemberDraft ?? createTeamMemberDraft()),
    selectedResourcesByType: {
      ...currentCache,
      [resourceType]: {
        ...(currentCache[resourceType] ?? {}),
        [normalizedId]: resource,
      },
    },
  };
}

