function getInputValue(root, selector, fallback) {
  const value = root.querySelector(selector)?.value?.trim();
  return value || fallback;
}

function getCheckedValue(root, selector, fallback) {
  return root.querySelector(`${selector}:checked`)?.value ?? fallback;
}

function updateOriginalScriptSubmitState(workbench) {
  const draft = workbench.ui.originalScriptDraft;
  const submit = workbench.root.querySelector('[data-action="submit-original-script-settings"]');
  if (!submit) {
    return;
  }

  submit.disabled = !(
    draft.fileName?.trim() &&
    draft.inspiration?.trim() &&
    draft.episodeCount
  );
}

function normalizeRoutePath(pathname) {
  const path = String(pathname ?? "/").trim() || "/";
  const normalized = path.replace(/\/+$/, "") || "/";
  if (normalized === "/app.html") {
    return "/";
  }
  return normalized;
}

function isCanvasNavTab(tab) {
  return tab === "tools" || tab === "new-canvas";
}

function canvasListRouteToken(workbench) {
  return workbench?.ui?.activeNavTab === "new-canvas" ? "new-canvas" : "tools";
}

function canvasDetailRouteToken(workbench) {
  return workbench?.ui?.activeNavTab === "new-canvas" ? "new-canvas-canvas" : "tools-canvas";
}

function readWorkbenchRouteToken(locationLike = globalThis.window?.location) {
  const hashToken = String(locationLike?.hash ?? "").replace(/^#/, "").trim();
  if (hashToken) {
    return hashToken;
  }
  const pathToken = PUBLIC_PATH_TOKENS.get(normalizeRoutePath(locationLike?.pathname));
  return pathToken ?? "";
}

function deriveInitialNavTab(hash, session = {}) {
  const token = String(hash || "").replace(/^#/, "");
  if (!token) {
    return "home";
  }
  if (parseEpisodeRouteToken(token) || parseProjectRouteToken(token)) {
    return "project";
  }
  if (token === "community") {
    return "community";
  }
  if (token === "media-library") {
    return "media-library";
  }
  if (token === "home") {
    return "home";
  }
  if (token === "director") {
    return "director";
  }
  if (
    token === "asset-prep-section" ||
    token === "project-detail" ||
    token === "storyboard-workbench" ||
    token === "episode-workbench" ||
    token === "project"
  ) {
    return "project";
  }
  if (token === "script") {
    return "script";
  }
  if (token === "prompts") {
    return "prompts";
  }
  if (token === "library") {
    return "library";
  }
  if (token === "tools" || token === "tools-canvas") {
    return "tools";
  }
  if (token === "new-canvas" || token === "new-canvas-canvas") {
    return isNewCanvasEnabled(session) ? "new-canvas" : "home";
  }
  if (token === "team" || token.startsWith("team-dashboard")) {
    if (isTeamMemberSession(session)) {
      return "project";
    }
    return "team";
  }
  return "project";
}

async function syncAnnouncementsFromApi(workbench) {
  if (typeof workbench.api?.getAnnouncements !== "function") {
    workbench.ui.announcements = [];
    workbench.ui.announcementVersion = "";
    workbench.ui.announcementsLoaded = true;
    workbench.ui.announcementError = "";
    syncAnnouncementUnreadState(workbench);
    return;
  }

  workbench.ui.announcementsLoading = true;
  try {
    const result = await workbench.api.getAnnouncements();
    const data = result?.data && typeof result.data === "object" ? result.data : result;
    workbench.ui.announcements = normalizeAnnouncements(data?.announcements);
    workbench.ui.announcementVersion = String(data?.version ?? "");
    workbench.ui.announcementsLoaded = true;
    workbench.ui.announcementError = "";
    if (workbench.ui.announcementPanelOpen === true) {
      markAnnouncementsSeen(workbench);
    }
  } catch (error) {
    workbench.ui.announcementError = friendlyError(error);
  } finally {
    workbench.ui.announcementsLoading = false;
    syncAnnouncementUnreadState(workbench);
  }
}

function normalizeAnnouncements(value) {
  return Array.isArray(value)
    ? value.map(normalizeAnnouncement).filter((announcement) => announcement.title)
    : [];
}

function normalizeAnnouncement(announcement = {}) {
  return {
    id: String(announcement.id ?? ""),
    title: String(announcement.title ?? "").trim(),
    body: String(announcement.body ?? ""),
    actionLabel: String(announcement.actionLabel ?? announcement.action_label ?? "").trim(),
    actionUrl: String(announcement.actionUrl ?? announcement.action_url ?? "").trim(),
    sortOrder: Number(announcement.sortOrder ?? announcement.sort_order ?? 100),
    updatedAt: String(announcement.updatedAt ?? announcement.updated_at ?? ""),
  };
}

function syncAnnouncementUnreadState(workbench) {
  const storedSeenVersion = readAnnouncementSeenVersion(workbench.session);
  const seenVersion = String(workbench.ui.announcementSeenVersion || storedSeenVersion || "");
  const version = String(workbench.ui.announcementVersion || "");
  const hasAnnouncements = Array.isArray(workbench.ui.announcements) && workbench.ui.announcements.length > 0;
  workbench.ui.announcementSeenVersion = seenVersion;
  workbench.ui.announcementUnread = Boolean(hasAnnouncements && version && (!seenVersion || version > seenVersion));
}

function markAnnouncementsSeen(workbench) {
  const version = String(workbench.ui.announcementVersion || "");
  if (!version) {
    syncAnnouncementUnreadState(workbench);
    return;
  }
  writeAnnouncementSeenVersion(workbench.session, version);
  workbench.ui.announcementSeenVersion = version;
  syncAnnouncementUnreadState(workbench);
}

function readAnnouncementSeenVersion(session = {}) {
  const key = announcementStorageKey(session);
  if (!key) {
    return "";
  }
  try {
    return String(announcementStorage()?.getItem(key) ?? "");
  } catch {
    return "";
  }
}

function writeAnnouncementSeenVersion(session = {}, version = "") {
  const key = announcementStorageKey(session);
  if (!key || !version) {
    return;
  }
  try {
    announcementStorage()?.setItem(key, version);
  } catch {
    // Local unread state is best-effort; announcement display still works without storage.
  }
}

function announcementStorageKey(session = {}) {
  const sessionKey = announcementSessionKey(session);
  return sessionKey ? `${ANNOUNCEMENT_SEEN_STORAGE_PREFIX}:${sessionKey}` : "";
}

function announcementSessionKey(session = {}) {
  const user = session?.user ?? {};
  const teamMember = user.teamMember ?? {};
  const teamMemberId = String(teamMember.id ?? teamMember.memberId ?? teamMember.memberAccount ?? "").trim();
  if (teamMemberId) {
    return `team-member:${encodeURIComponent(teamMemberId)}`;
  }
  const userId = String(user.id ?? user.phone ?? user.email ?? "").trim();
  return userId ? `user:${encodeURIComponent(userId)}` : "";
}

function announcementStorage() {
  return globalThis.window?.localStorage ?? globalThis.localStorage ?? null;
}

const LINGXI_COMMUNITY_STORAGE_KEY = "lingxi-community-board";

function readLingxiCommunityData() {
  const fallback = createDefaultLingxiCommunityData();
  try {
    const parsed = JSON.parse(localStorage.getItem(LINGXI_COMMUNITY_STORAGE_KEY) || "null");
    return {
      posts: normalizeLingxiCommunityPosts(Array.isArray(parsed?.posts) ? parsed.posts : fallback.posts),
      features: normalizeLingxiCommunityFeatures(Array.isArray(parsed?.features) ? parsed.features : fallback.features),
    };
  } catch {
    return fallback;
  }
}

function writeLingxiCommunityData(data) {
  try {
    localStorage.setItem(LINGXI_COMMUNITY_STORAGE_KEY, JSON.stringify({
      posts: Array.isArray(data?.posts) ? data.posts : [],
      features: Array.isArray(data?.features) ? data.features : [],
    }));
  } catch {
    // Keep the community usable even if storage is unavailable.
  }
}

function mergeLingxiCommunityItems(primaryItems = [], nextItems = []) {
  const merged = [];
  const seen = new Set();
  for (const item of [...primaryItems, ...nextItems]) {
    const id = String(item?.id ?? "").trim();
    const key = id || `${String(item?.title ?? "").trim()}::${String(item?.content ?? "").trim()}`;
    if (!key || seen.has(key)) continue;
    seen.add(key);
    merged.push(item);
  }
  return merged;
}

function normalizeLingxiCommunityPosts(posts = []) {
  return posts.map((post) => {
    const likedBy = Array.isArray(post?.likedBy) ? post.likedBy.map(String) : [];
    const comments = Array.isArray(post?.comments)
      ? post.comments.map((comment) => ({
        ...comment,
        replies: Array.isArray(comment?.replies) ? comment.replies : [],
      }))
      : [];
    return {
      ...post,
      userId: String(post?.userId || inferCommunityUserIdFromAuthor(post?.author) || ""),
      likedBy,
      likes: Number(post?.likes ?? likedBy.length ?? 0),
      comments,
    };
  });
}

function normalizeLingxiCommunityFeatures(features = []) {
  return features.map((feature) => ({
    ...feature,
    votes: Number(feature?.votes ?? 0),
    voterIds: Array.isArray(feature?.voterIds) ? feature.voterIds.map(String) : [],
  }));
}

async function loadLingxiCommunityBoard(workbench) {
  if (typeof workbench.api?.getCommunityBoard !== "function") {
    return;
  }
  try {
    const data = await workbench.api.getCommunityBoard();
    writeLingxiCommunityData(data);
    workbench.ui.communityPosts = Array.isArray(data?.posts) ? data.posts : [];
    workbench.ui.communityFeatures = Array.isArray(data?.features) ? data.features : [];
    render(workbench);
  } catch {
    const data = readLingxiCommunityData();
    workbench.ui.communityPosts = data.posts;
    workbench.ui.communityFeatures = data.features;
  }
}

async function loadPersonalMediaLibrarySurface(workbench) {
  if (
    typeof workbench?.api?.getPersonalMediaLibrary !== "function" ||
    typeof workbench?.api?.getPersonalMediaLibrarySummary !== "function"
  ) {
    workbench.ui.personalMediaLibraryError = "当前环境暂不支持个人素材库。";
    workbench.ui.personalMediaLibraryLoading = false;
    render(workbench);
    return;
  }
  const requestId = (workbench.personalMediaLibraryRequestId ?? 0) + 1;
  workbench.personalMediaLibraryRequestId = requestId;
  workbench.ui.personalMediaLibraryLoading = true;
  workbench.ui.personalMediaLibraryError = "";
  render(workbench);
  try {
    const query = {
      media: workbench.ui.personalMediaLibraryMediaFilter ?? "all",
      range: workbench.ui.personalMediaLibraryRangeFilter ?? "all",
      keyword: workbench.ui.personalMediaLibraryKeyword ?? "",
    };
    const [summary, payload] = await Promise.all([
      workbench.api.getPersonalMediaLibrarySummary(query),
      workbench.api.getPersonalMediaLibrary({
        ...query,
        page: workbench.ui.personalMediaLibraryPage ?? 1,
        pageSize: PERSONAL_MEDIA_LIBRARY_PAGE_SIZE,
      }),
    ]);
    if (workbench.personalMediaLibraryRequestId !== requestId) {
      return;
    }
    workbench.ui.personalMediaLibrarySummary = summary ?? null;
    workbench.ui.personalMediaLibraryRows = Array.isArray(payload?.data) ? payload.data : [];
    workbench.ui.personalMediaLibraryMeta = payload?.meta ?? {
      page: workbench.ui.personalMediaLibraryPage ?? 1,
      pageSize: PERSONAL_MEDIA_LIBRARY_PAGE_SIZE,
      total: workbench.ui.personalMediaLibraryRows.length,
      totalPages: 1,
    };
  } catch (error) {
    if (workbench.personalMediaLibraryRequestId !== requestId) {
      return;
    }
    workbench.ui.personalMediaLibraryRows = [];
    workbench.ui.personalMediaLibrarySummary = null;
    workbench.ui.personalMediaLibraryMeta = null;
    workbench.ui.personalMediaLibraryError = friendlyError(error) || "素材库加载失败。";
  } finally {
    if (workbench.personalMediaLibraryRequestId === requestId) {
      workbench.ui.personalMediaLibraryLoading = false;
      render(workbench);
    }
  }
}

