function createLingxiCommunityItem(input = {}) {
  const createdAt = input.createdAt || new Date().toISOString();
  return {
    id: input.id || `community-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    title: String(input.title || "").trim(),
    content: String(input.content || "").trim(),
    category: String(input.category || "问题反馈"),
    author: String(input.author || "灵曦用户"),
    userId: String(input.userId || ""),
    createdAt,
    createdAtLabel: formatCommunityDate(createdAt),
    likedBy: Array.isArray(input.likedBy) ? input.likedBy : [],
    likes: Number(input.likes ?? 0),
    comments: Array.isArray(input.comments) ? input.comments : [],
    promptMeta: input.promptMeta && typeof input.promptMeta === "object" ? input.promptMeta : null,
  };
}

function formatCommunityDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return `${date.getMonth() + 1}月${date.getDate()}日 ${String(date.getHours()).padStart(2, "0")}:${String(date.getMinutes()).padStart(2, "0")}`;
}

function communityAuthorLabel(session) {
  const phone = String(session?.user?.phone ?? "");
  return phone ? `创作者 ${phone.slice(-4)}` : "灵曦用户";
}

function communitySessionKey(session = {}) {
  return String(session?.user?.id || session?.user?.phone || session?.user?.email || "").trim();
}

function isCommunityOwnPostRecord(post = {}, session = {}) {
  const userKey = communitySessionKey(session);
  const phoneTail = String(session?.user?.phone ?? "").slice(-4);
  return Boolean(userKey && (String(post.userId || "") === userKey || (phoneTail && String(post.author || "").endsWith(phoneTail))));
}

function inferCommunityUserIdFromAuthor(author) {
  const match = String(author ?? "").match(/创作者\s*(\d{4})$/);
  return match ? match[1] : "";
}

function deriveInitialCanvasProjectView(hash) {
  const token = String(hash || "").replace(/^#/, "");
  return token === "tools-canvas" || token === "new-canvas-canvas" ? "detail" : "list";
}

function deriveInitialLibraryTeamRoute(hash) {
  const token = String(hash || "").replace(/^#/, "");
  if (token.startsWith("team-dashboard")) {
    return "team-dashboard";
  }
  if (token === "team") {
    return "team";
  }
  return "assets";
}

function normalizeTeamDashboardTab(tab) {
  const normalizedTab = String(tab ?? "");
  return TEAM_DASHBOARD_TABS.has(normalizedTab) ? normalizedTab : "member-consumption";
}

function normalizeTeamDashboardDateRange(range) {
  const normalizedRange = String(range ?? "");
  return TEAM_DASHBOARD_DATE_RANGES.has(normalizedRange) ? normalizedRange : "today";
}

function deriveInitialTeamDashboardTab(hash) {
  const token = String(hash || "").replace(/^#/, "");
  if (token === "team-dashboard-project-cost") {
    return "project-cost";
  }
  if (token === "team-dashboard-ranking") {
    return "ranking";
  }
  return "member-consumption";
}

function teamDashboardHash(tab) {
  const normalizedTab = normalizeTeamDashboardTab(tab);
  return normalizedTab === "member-consumption" ? "team-dashboard" : `team-dashboard-${normalizedTab}`;
}

function deriveInitialProjectPanelMode(hash) {
  const token = String(hash || "").replace(/^#/, "");
  if (parseEpisodeRouteToken(token)) {
    return "episode-workbench";
  }
  if (parseProjectRouteToken(token)) {
    return "detail";
  }
  if (token === "episode-workbench" || token === "storyboard-workbench") {
    return "episode-workbench";
  }
  if (token === "asset-prep-section" || token === "project-detail") {
    return "detail";
  }
  return "library";
}

function deriveInitialProjectInteriorSection(hash) {
  const token = String(hash || "").replace(/^#/, "");
  const projectRoute = parseProjectRouteToken(token);
  if (projectRoute) {
    return projectRoute.section;
  }
  if (parseEpisodeRouteToken(token) || token === "episode-workbench" || token === "storyboard-workbench") {
    return "episodes";
  }
  return "overview";
}

